'use strict';
function needPage(){
 main.innerHTML='<div class="heading-row"><div><p class="hello">'+icon('sun')+' A little connection, a little closer.</p><h1>What would you like to say?</h1><p class="subtext">Your needs. Your pace. A voice that feels like home.</p></div>'+'<div class="view-tools"><button class="patient-toggle" data-action="patient-view">'+icon('grid')+'<span>Patient view</span></button>'+languageButton()+'</div></div><section class="welcome-banner"><div class="banner-left"><span class="banner-icon">'+icon('volume')+'</span><div><h2>A familiar voice makes all the difference.</h2><p>'+(recordingIds.size?recordingIds.size+' of '+state.phrases.length+' phrases have your family’s voice.':'Bring these words to life in your family’s own language.')+'</p></div></div>'+waveform()+'<a class="text-button" href="#studio">Record your voice '+icon('arrow')+'</a></section><div class="board-tools"><div class="filters" role="group" aria-label="Filter needs">'+['All needs','Essentials','Comfort','People','Feelings'].map((c,i)=>'<button class="filter '+(category===c?'active':'')+'" data-category="'+c+'" aria-pressed="'+(category===c)+'">'+icon(['grid','home','heart','people','sun'][i])+c+'</button>').join('')+'</div><button class="add-phrase" data-action="add" aria-label="Add a phrase">'+icon('plus')+' Add a phrase</button></div><div class="need-layout"><div><div class="phrase-grid" id="phrase-grid"></div><p class="board-caption"><span>Tap a picture to speak. Take all the time you need.</span><span id="visible-count"></span></p></div><section class="selected-panel" id="selected-panel" aria-label="Selected phrase"></section></div><div class="practice-nudge"><div class="practice-nudge-left"><span>'+icon('sprout')+'</span><div><h3>A few words, together?</h3><p>A gentle practice moment when you both feel ready.</p></div></div><a href="#practice" class="text-button">Let’s practise '+icon('arrow')+'</a></div>';
 renderGrid();renderSelected();
}
function renderGrid(){const phrases=state.phrases.filter(p=>category==='All needs'||p.category===category);$('#phrase-grid').innerHTML=phrases.length?phrases.map(p=>'<button class="phrase-card '+(p.id===selectedId?'selected':'')+'" data-phrase="'+esc(p.id)+'" aria-label="'+esc(p.label)+': '+esc(p.phrase)+'" aria-pressed="'+(p.id===selectedId)+'"><span class="audio-dot '+(recordingIds.has(p.id)?'recorded':'')+'">'+icon(recordingIds.has(p.id)?'volume':'mic')+'</span>'+art(p)+'<strong>'+esc(p.label)+'</strong><small>'+esc(p.category)+'</small></button>').join(''):'<p class="empty-state">No phrases here yet. Add one that matters to your family.</p>';$('#visible-count').textContent=phrases.length+' phrases'}
function renderSelected(){const p=state.phrases.find(x=>x.id===selectedId)||state.phrases[0];if(!p){$('#selected-panel').innerHTML='<h2>Your words belong here.</h2><button class="primary-button" data-action="add">Add your first phrase</button>';return}selectedId=p.id;const has=recordingIds.has(p.id);$('#selected-panel').innerHTML='<div class="panel-eyebrow"><span>LET’S SAY IT TOGETHER</span>'+icon('heart')+'</div>'+art(p)+'<h2>'+esc(p.phrase)+'</h2><p class="phrase-translation">'+(has?esc(p.recordedLanguage||state.profile.language)+' · Recorded by '+esc(p.recordedBy||state.profile.caregiver):'English sample · Add your family’s recording')+'</p><div class="voice-label">'+icon(has?'mic':'volume')+(has?'A familiar voice, just for you':'Device voice preview')+'</div><button class="primary-button" data-action="speak" data-id="'+esc(p.id)+'">'+icon('volume')+'<span>Say it aloud</span></button><button class="panel-record" data-action="record" data-id="'+esc(p.id)+'">'+icon('mic')+(has?'Listen & re-record':'Make it your voice')+'</button><div class="panel-divider"></div><div class="care-tip"><span>'+icon('sprout')+'</span><div><strong>Leave a little room.</strong><p>Give them time to respond. A word, a look, a gesture — it all counts.</p></div></div>'}
function practicePage(){
 if(session){renderSession();return}
 main.innerHTML=heading('A LITTLE AT A TIME','Connection comes with practice.','Familiar pictures. Familiar words. No rush to get it right.')+'<section class="practice-hero"><div><p class="eyebrow">YOUR NEXT SMALL STEP</p><h2>Five familiar pictures.<br>One moment together.</h2><p>A short, gentle practice with everyday words from your board. You set the pace; we’ll follow your lead.</p><button class="primary-button" data-start="words">'+icon('play')+' Begin a gentle session</button><p class="small-note">5 pictures · Caregiver guided · Pause any time</p></div><div class="hero-flower" aria-hidden="true"><svg viewBox="0 0 170 150" fill="none"><circle cx="90" cy="73" r="61" fill="#e1e8d5"/><path d="M88 136V66" stroke="#7c9668" stroke-width="3"/><path d="M88 108C49 109 44 89 48 72c30 2 40 14 40 36ZM88 93c35 0 48-21 43-40-29 2-43 18-43 40Z" fill="#b6c69f" stroke="#91a779" stroke-width="1.5"/><path d="M88 76c-21-1-29-15-21-24-18-13-4-33 11-25 4-21 29-20 30 0 20-7 31 15 14 25 8 16-9 31-22 19" fill="#e7d8ad" stroke="#bba97d" stroke-width="1.5"/><circle cx="94" cy="48" r="12" fill="#c5b373"/><path d="m36 33 2-8m3 14 8-3M139 111l7 3m-11 4 2 7" stroke="#b5bc9c" stroke-width="2"/></svg></div></section><div class="section-head"><div><h2>Find your own rhythm.</h2><p>Choose what feels comfortable today.</p></div></div><div class="practice-types">'+[
 ['words','spark','Find a word','Look at a picture. Try the word. Ask for a first-sound cue or listen together.','Practise words'],
 ['scripts','book','Everyday phrases','Rehearse a useful phrase, one small part at a time. Familiarity is the starting point.','Practise phrases'],
 ['pace','people','Any way counts','Say it, point to it, or gesture. Celebrate getting the message across in any way.','Connect together']
 ].map(([type,symbol,title,desc,cta])=>'<button class="type-card" data-start="'+type+'"><span class="type-icon">'+icon(symbol)+'</span><h3>'+title+'</h3><p>'+desc+'</p><span class="text-button">'+cta+' '+icon('arrow')+'</span></button>').join('')+'</div><p class="practice-note">'+icon('help')+'Concept practice activities; not a clinical assessment. A speech-language therapist should guide rehabilitation.</p>';
}
function startSession(type){if(!state.phrases.length){toast('Add a phrase to your board first.');return}stopAudio();const score=id=>state.sessions.flatMap(s=>s.attempts).filter(x=>x.id===id).reduce((n,x)=>n+(x.result==='independent'?2:x.result==='supported'?1:0),0);const ranked=[...state.phrases].sort((a,b)=>score(a.id)-score(b.id));session={type,queue:ranked.slice(0,5).sort(()=>Math.random()-.5),index:0,attempts:[],started:Date.now(),cueShown:state.level===0,completed:false};renderSession()}
function renderSession(){
 if(session.completed){const successes=session.attempts.filter(a=>a.result!=='try-again').length;main.innerHTML='<div class="session-wrap"><div class="summary-box"><span class="summary-icon">'+icon('sprout')+'</span><p class="eyebrow">A MOMENT WORTH CELEBRATING</p><h1>You showed up for each other.</h1><p>Every attempt is a moment of connection. Rest when you need to, and come back when it feels right.</p><div class="summary-stats"><div><strong>'+session.attempts.length+'</strong><span>pictures explored</span></div><div><strong>'+successes+'</strong><span>messages shared</span></div><div><strong>'+Math.max(1,Math.ceil((Date.now()-session.started)/60000))+'</strong><span>minutes together</span></div></div><p>'+esc(session.nextMessage)+'</p><button class="primary-button" data-action="finish-practice">Back to practice '+icon('arrow')+'</button> <a href="#progress" class="secondary-button" data-action="view-progress">View our progress</a></div></div>';return}
 const p=session.queue[session.index],type=session.type,title=type==='words'?'What is this?':type==='scripts'?'Let’s try this phrase.':'How would you share this?';
 const scaffold=type==='scripts'?p.phrase.split(/\s+/).slice(0,Math.max(1,Math.ceil(p.phrase.split(/\s+/).length/2))).join(' ')+'…':p.cue||p.label.slice(0,1)+'…';
 main.innerHTML='<div class="session-wrap"><div class="session-top"><button class="text-button" data-action="pause">'+icon('back')+' Pause practice</button><span>Picture '+(session.index+1)+' of '+session.queue.length+'</span></div><div class="progress-track" role="progressbar" aria-label="Session progress" aria-valuemin="0" aria-valuemax="'+session.queue.length+'" aria-valuenow="'+session.index+'"><div class="progress-fill" style="width:'+(session.index/session.queue.length*100)+'%"></div></div><section class="practice-word"><p class="eyebrow">'+(type==='words'?'WORD FINDING':type==='scripts'?'EVERYDAY PHRASES':'ANY WAY COUNTS')+'</p>'+art(p)+'<h1>'+title+'</h1><p>'+(type==='pace'?'Try saying it, pointing to the picture, or using a gesture.':type==='scripts'?'Listen together, then give the phrase a try at your own pace.':'Give them space to find the word. There is no timer.')+'</p><button class="secondary-button" data-action="practice-listen">'+icon('volume')+' Listen together</button>'+(type!=='pace'?'<button class="secondary-button" data-action="cue">'+icon('spark')+' '+(type==='scripts'?'Start the phrase':'A little hint')+'</button>':'')+'<div id="practice-cue" '+(session.cueShown?'':'hidden')+' class="cue">'+esc(scaffold)+'<p class="field-hint">'+(type==='words'&&!p.recordedLanguage?'English sample cue · Set a household cue in the studio.':'A starting point, whenever you need it.')+'</p></div></section><div class="session-controls"><h3>Caregiver, how did that feel?</h3><div class="rating-buttons"><button data-result="try-again">Let’s revisit it</button><button data-result="supported">With a little help</button><button data-result="independent">'+icon('check')+' '+(type==='pace'?'Message understood':'Got it together')+'</button></div><p class="small-note">Caregiver observations only. Any successful communication counts.</p></div></div>';
}
function rateAttempt(result){if(!session||session.completed)return;session.attempts.push({id:session.queue[session.index].id,result,cue:session.cueShown});session.index++;if(session.index>=session.queue.length){const ratio=session.attempts.filter(a=>a.result==='independent').length/session.queue.length;state.level=ratio>=.8?Math.min(2,state.level+1):ratio<.4?Math.max(0,state.level-1):state.level;session.nextMessage=state.level===0?'Next time, we’ll offer a little hint from the start.':state.level===2?'Next time, try giving a little extra space before a hint.':'Next time, a little hint is always there if you need it.';state.sessions.push({date:new Date().toISOString(),type:session.type,attempts:session.attempts,seconds:Math.round((Date.now()-session.started)/1000),level:state.level});persist();profileUi();session.completed=true}else session.cueShown=state.level===0;stopAudio();renderSession()}
function studioPage(){main.innerHTML=heading('FAMILIAR WORDS. YOUR VOICE.','Make this space feel like home.','Record the words you actually use. In the language you share.')+'<section class="welcome-banner"><div class="banner-left"><span class="banner-icon">'+icon('mic')+'</span><div><h2>'+recordingIds.size+' of '+state.phrases.length+' phrases in a familiar voice.</h2><p>Record a full phrase and, if helpful, add a first-sound cue.</p></div></div>'+waveform()+'</section><div class="studio-toolbar"><input id="phrase-search" class="search-input" placeholder="Find a word or phrase…" aria-label="Search phrases" value="'+esc(search)+'"><button class="primary-button" data-action="add">'+icon('plus')+' Add a personal phrase</button></div><div class="studio-table"><div class="studio-row table-head"><span>YOUR PHRASES</span><span>FAMILIAR VOICE</span><span>LANGUAGE</span><span></span></div><div id="studio-rows"></div></div><div class="settings-actions"><button class="secondary-button" data-action="settings">'+icon('settings')+' Household settings</button><button class="secondary-button" data-action="export">'+icon('download')+' Save a backup</button><button class="secondary-button" data-action="import">'+icon('upload')+' Restore a backup</button></div><p class="practice-note">'+icon('heart')+'Photos and recordings stay in this browser on this device. Save a backup to keep a copy.</p>';renderStudioRows()}
function renderStudioRows(){const phrases=state.phrases.filter(p=>(p.label+' '+p.phrase).toLowerCase().includes(search.toLowerCase()));$('#studio-rows').innerHTML=phrases.map(p=>'<div class="studio-row"><div class="studio-phrase">'+art(p)+'<div><strong>'+esc(p.label)+'</strong><small>'+esc(p.phrase)+'</small></div></div><span class="status-tag '+(recordingIds.has(p.id)?'done':'')+'">'+(recordingIds.has(p.id)?'Voice recorded':'Ready to record')+'</span><span class="studio-language">'+(recordingIds.has(p.id)?esc(p.recordedLanguage||state.profile.language):'English sample')+'</span><div class="row-actions"><button class="secondary-button" data-action="record" data-id="'+esc(p.id)+'" aria-label="Record '+esc(p.label)+'">'+icon('mic')+' Record</button><button class="icon-button" data-action="edit" data-id="'+esc(p.id)+'" aria-label="Edit '+esc(p.label)+'">'+icon('edit')+'</button></div></div>').join('')||'<p class="empty-state">No matching phrases. Try another word.</p>'}
function progressPage(){const attempts=state.sessions.flatMap(s=>s.attempts),successes=attempts.filter(a=>a.result!=='try-again').length;const week=Array.from({length:7},(_,i)=>{const day=new Date();day.setDate(day.getDate()-6+i);const count=state.sessions.filter(s=>new Date(s.date).toDateString()===day.toDateString()).reduce((n,s)=>n+s.attempts.length,0);return{day:day.toLocaleDateString('en',{weekday:'short'}),count}}),max=Math.max(5,...week.map(x=>x.count));
 main.innerHTML=heading('EVERY ATTEMPT COUNTS','A little progress, a lot of heart.','A record of your moments together. Built from what you’ve done here.')+'<div class="stats-grid">'+[['Practice moments',state.sessions.length,'Small steps, taken together','sprout'],['Messages shared',successes,'With or without a little help','people'],['Need board taps',state.uses.length,'Everyday communication attempts','volume']].map(([title,value,sub,symbol])=>'<section class="stat-card"><div class="stat-top"><span>'+title+'</span>'+icon(symbol)+'</div><strong>'+value+'</strong><small>'+sub+'</small></section>').join('')+'</div><div class="progress-layout"><section class="chart-card"><h2>Your week, one moment at a time.</h2><p>Pictures explored in practice over the last 7 days</p><div class="bar-chart" aria-label="Practice pictures per day">'+week.map((x,i)=>'<div class="bar-column '+(i===6?'today':'')+'"><span>'+x.count+'</span><div class="bar" style="height:'+Math.max(2,x.count/max*130)+'px"></div><small>'+x.day+'</small></div>').join('')+'</div><p style="margin-top:22px">Consistency is an invitation, never a deadline.</p></section><section class="history-card"><h2>Moments we’ve shared.</h2>'+(state.sessions.length?state.sessions.slice(-5).reverse().map(s=>'<div class="history-item"><div><strong>'+({words:'Word finding',scripts:'Everyday phrases',pace:'Any way counts'}[s.type]||'Practice')+'</strong><small>'+new Date(s.date).toLocaleDateString('en-KE',{day:'numeric',month:'short'})+' · '+s.attempts.length+' pictures</small></div><span>'+s.attempts.filter(a=>a.result!=='try-again').length+' shared</span></div>').join(''):'<div class="empty-state">'+icon('sprout')+'<p style="margin:13px 0 20px">Your story starts with one small moment.</p><a href="#practice" class="text-button" style="justify-content:center">Begin together '+icon('arrow')+'</a></div>')+'</section></div><div class="settings-actions"><button class="secondary-button" data-action="export">'+icon('download')+' Save a backup</button><a class="secondary-button" href="#practice">'+icon('sprout')+' A little practice</a></div><p class="practice-note">'+icon('help')+'Caregiver observations show engagement, not a measure of clinical recovery. Share them with your therapist for context.</p>';
}
function navigate(){const next=location.hash.slice(1);route=['need','practice','studio','progress'].includes(next)?next:'need';if(route!=='practice'&&session?.completed)session=null;stopAudio();$$('[data-route]').forEach(a=>{a.classList.toggle('active',a.dataset.route===route);if(a.dataset.route===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#page-name').textContent={need:'Need board',practice:'Practice together',studio:'Caregiver studio',progress:'Our progress'}[route];({need:needPage,practice:practicePage,studio:studioPage,progress:progressPage}[route])();profileUi()}
